examples.code:
text = "i like cats i like dogs i like cats"
words = text.split()
counts = {}
for i in range(len(words) - 1):
    if words[i] == "like":
        nxt = words[i + 1]
        counts[nxt] = counts.get(nxt, 0) + 1
print(counts)

